import fitz, ezdxf, sys
d = r"C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\13-11-2026\521113-05"
doc = fitz.open(d + r"\521113-05.pdf")
for i, p in enumerate(doc):
    t = p.get_text()
    print("=== page", i, p.rect, "068185" in t)
    print(t[:1500])
for name in ["300-30.dxf", "200-30.dxf", r"Sua_loi\26-068185T.dxf", r"Sua_loi\26-068185F.dxf"]:
    print("=== DXF", name)
    dx = ezdxf.readfile(d + "\\" + name)
    for e in dx.modelspace():
        t = e.dxftype()
        if t == "LINE":
            print(t, e.dxf.layer, tuple(round(v, 2) for v in e.dxf.start)[:2], tuple(round(v, 2) for v in e.dxf.end)[:2])
        elif t == "ARC":
            print(t, e.dxf.layer, tuple(round(v, 2) for v in e.dxf.center)[:2], round(e.dxf.radius, 2), round(e.dxf.start_angle, 1), round(e.dxf.end_angle, 1))
        elif t == "CIRCLE":
            print(t, e.dxf.layer, tuple(round(v, 2) for v in e.dxf.center)[:2], round(e.dxf.radius, 2))
        elif t in ("TEXT", "MTEXT"):
            print(t, e.dxf.layer, e.dxf.text if t == "TEXT" else e.text)
        else:
            print(t, e.dxf.layer)

