import ezdxf
d = r"C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\13-11-2026\521113-05"
dx = ezdxf.readfile(d + r"\300-30.dxf")
msp = dx.modelspace()
for ins in msp.query("INSERT"):
    print("=== INSERT", ins.dxf.name, ins.dxf.layer, tuple(round(v, 2) for v in ins.dxf.insert)[:2], ins.dxf.get("rotation", 0), ins.dxf.get("xscale", 1), ins.dxf.get("yscale", 1))
    for e in dx.blocks[ins.dxf.name]:
        t = e.dxftype()
        lt = e.dxf.get("linetype", "BYLAYER")
        col = e.dxf.get("color", 256)
        if t == "LINE":
            print(" ", t, e.dxf.layer, lt, col, tuple(round(v, 2) for v in e.dxf.start)[:2], tuple(round(v, 2) for v in e.dxf.end)[:2])
        elif t == "ARC":
            print(" ", t, e.dxf.layer, lt, col, tuple(round(v, 2) for v in e.dxf.center)[:2], round(e.dxf.radius, 2), round(e.dxf.start_angle, 1), round(e.dxf.end_angle, 1))
        elif t == "CIRCLE":
            print(" ", t, e.dxf.layer, lt, col, tuple(round(v, 2) for v in e.dxf.center)[:2], round(e.dxf.radius, 2))
        elif t in ("TEXT", "MTEXT"):
            print(" ", t, e.dxf.layer, e.dxf.text if t == "TEXT" else e.text)
        else:
            print(" ", t, e.dxf.layer, lt)
for dim in msp.query("DIMENSION"):
    print("DIM", dim.dxf.get("text", ""), round(dim.get_measurement(), 2) if hasattr(dim, "get_measurement") else "")
for lay in dx.layers:
    print("LAYER", lay.dxf.name, lay.dxf.linetype, lay.dxf.color)

